       font-weight: 700;
     }

     .error-message:empty {
       display: none;
     }

     .form-status {
       min-height: 1.5rem;
       margin: 0.25rem 0 1rem;
       color: var(--success);
       font-weight: 700;
     }

     button {
       width: 100%;
       min-height: 3.15rem;
       padding: 0.9rem 1rem;
       color: #ffffff;
       background: var(--primary);
       border: 0;
       border-radius: 999px;
       box-shadow: 0 12px 28px rgba(37, 87, 214, 0.28);
       cursor: pointer;
       font: inherit;
       font-weight: 800;
       transition: background 160ms ease, box-shadow 160ms ease, transform 160ms ease;
     }

     button:hover {
       background: var(--primary-dark);
       transform: translateY(-1px);
     }

     button:focus {
       outline: 3px solid var(--ring);
       outline-offset: 3px;
     }

     button:active {
       transform: translateY(0);
     }

     @media (max-width: 48rem) {
       main {
         padding: 1rem;
       }

       .support-card {
         grid-template-columns: 1fr;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       *,
       *::before,
       *::after {
         scroll-behavior: auto !important;
         transition-duration: 0.01ms !important;
         animation-duration: 0.01ms !important;
         animation-iteration-count: 1 !important;
       }
     }

     @media (forced-colors: active) {
       .support-card,
       .intro,
       input,
       button {
         border: 1px solid CanvasText;
         box-shadow: none;
       }

       button {
         background: ButtonFace;
         color: ButtonText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="support-card" aria-labelledby="page-title">
       <div class="intro">
         <p class="eyebrow">Support</p>
         <h1 id="page-title">How can we help?</h1>
         <p class="intro-text">
           Send your contact details and our support team will get back to you with the next steps.
         </p>
       </div>

       <form id="support-form" novalidate>
         <p class="required-note">Fields marked with an asterisk (<span class="required-marker">*</span>) are required.</p>

         <div class="form-field">
           <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             required
             aria-describedby="full-name-error"
           >
           <p class="error-message" id="full-name-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="email">Email address <span class="required-marker" aria-hidden="true">*</span></label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             required
             aria-describedby="email-error"
           >
           <p class="error-message" id="email-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="phone">Phone number <span>(optional)</span></label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-help phone-error"
           >
           <p class="helper-text" id="phone-help">Use digits, spaces, parentheses, hyphens, or a leading plus sign, for example +1 555-123-4567.</p>
           <p class="error-message" id="phone-error" aria-live="polite"></p>
         </div>

         <p class="form-status" id="form-status" aria-live="polite"></p>
         <button type="submit">Send request</button>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#support-form");
     const statusMessage = document.querySelector("#form-status");
     const fields = {
       fullName: {
         input: document.querySelector("#full-name"),
         error: document.querySelector("#full-name-error"),
         validate(value) {
           return value.trim() ? "" : "Error: Enter your full name.";
         }
       },
       email: {
         input: document.querySelector("#email"),
         error: document.querySelector("#email-error"),
         validate(value) {
           const trimmed = value.trim();
           if (!trimmed) {
             return "Error: Enter your email address.";
           }

           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)
             ? ""
             : "Error: Enter a valid email address, such as name@example.com.";
         }
       },
       phone: {
         input: document.querySelector("#phone"),
         error: document.querySelector("#phone-error"),
         validate(value) {
           const trimmed = value.trim();
           if (!trimmed) {
             return "";
           }

           return /^\+?[0-9\s().-]{7,20}$/.test(trimmed)
             ? ""
             : "Error: Enter a phone number using digits, spaces, parentheses, hyphens, or a leading plus sign.";
         }
       }
     };

     function setFieldError(field, message) {
       field.error.textContent = message;
       if (message) {
         field.input.setAttribute("aria-invalid", "true");
       } else {
         field.input.removeAttribute("aria-invalid");
       }
     }

     function validateField(field) {
       const message = field.validate(field.input.value);
       setFieldError(field, message);
       return !message;
     }

     function validateForm() {
       let firstInvalidInput = null;

       Object.values(fields).forEach((field) => {
         const isValid = validateField(field);
         if (!isValid && !firstInvalidInput) {
           firstInvalidInput = field.input;
         }
       });

       return firstInvalidInput;
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener("input", () => {
         validateField(field);
         statusMessage.textContent = "";
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       const firstInvalidInput = validateForm();

       if (firstInvalidInput) {
         statusMessage.textContent = "";
         firstInvalidInput.focus();
         return;
       }

       form.reset();
       Object.values(fields).forEach((field) => setFieldError(field, ""));
       statusMessage.textContent = "Thanks, your support request is ready to send.";
     });
   </script>
 </body>
 </html>

')
